"""A stdlib-only MCP-style JSON-RPC server for the unified-sandbox-api e2e.

Run as the sandbox command (`python -c <this file>`) in a plain
`python:3.12-slim` image. Like a streamable-HTTP MCP server it refuses
requests whose `accept` header lacks `application/json` and
`text/event-stream` (400), hands out an `mcp-session-id` on `initialize` and
requires it afterwards, so a client that drops headers fails loudly.
"""

import json
import os
import uuid
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

PORT = int(os.environ.get("MCP_PORT", "8765"))
SESSIONS = set()


class Handler(BaseHTTPRequestHandler):
    def log_message(self, *args):
        pass

    def _send(self, status, body, headers=()):
        data = json.dumps(body).encode()
        self.send_response(status)
        self.send_header("content-type", "application/json")
        self.send_header("content-length", str(len(data)))
        for k, v in headers:
            self.send_header(k, v)
        self.end_headers()
        self.wfile.write(data)

    def do_GET(self):
        if self.path.startswith("/health"):
            self._send(200, {"ok": True})
        else:
            self._send(404, {"error": "not found"})

    def do_POST(self):
        if not self.path.startswith("/mcp"):
            return self._send(404, {"error": "not found"})
        accept = self.headers.get("accept", "")
        if "application/json" not in accept or "text/event-stream" not in accept:
            return self._send(
                400, {"error": "accept must list application/json and text/event-stream"}
            )
        req = json.loads(self.rfile.read(int(self.headers.get("content-length", 0))) or b"{}")
        method, rid = req.get("method"), req.get("id")
        if method == "initialize":
            sid = uuid.uuid4().hex
            SESSIONS.add(sid)
            result = {
                "protocolVersion": "2025-03-26",
                "capabilities": {"tools": {}},
                "serverInfo": {"name": "cua-e2e-mcp", "version": "1"},
            }
            return self._send(
                200, {"jsonrpc": "2.0", "id": rid, "result": result}, [("mcp-session-id", sid)]
            )
        if self.headers.get("mcp-session-id") not in SESSIONS:
            return self._send(400, {"error": "missing or unknown mcp-session-id"})
        if method == "tools/list":
            result = {
                "tools": [
                    {"name": "add", "inputSchema": {"type": "object"}},
                    {"name": "env", "inputSchema": {"type": "object"}},
                ]
            }
        elif method == "tools/call":
            p = req.get("params") or {}
            a = p.get("arguments") or {}
            if p.get("name") == "add":
                text = str(a["a"] + a["b"])
            else:
                text = os.environ.get(a.get("var", "GREETING"), "")
            result = {"content": [{"type": "text", "text": text}]}
        else:
            result = {}
        self._send(200, {"jsonrpc": "2.0", "id": rid, "result": result})


ThreadingHTTPServer(("0.0.0.0", PORT), Handler).serve_forever()

"""A trivial FastMCP server (streamable HTTP on :8765/mcp) for cua e2e tests."""
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("cua-e2e-mcp", host="0.0.0.0", port=8765)


@mcp.tool()
def add(a: int, b: int) -> int:
    """Add two integers."""
    return a + b


@mcp.tool()
def echo(text: str) -> str:
    """Echo text."""
    return text


@mcp.resource("mem://greeting")
def greeting() -> str:
    return "hello"


if __name__ == "__main__":
    mcp.run(transport="streamable-http")

"""Shared docs corpus, immutable generation, publication, and reader contract."""

import hashlib
import json
import logging
import re
import shutil
import sqlite3
import threading
import uuid
from datetime import datetime, timezone
from pathlib import Path

FORMAT_VERSION = 1
EMBEDDING = {"model": "all-MiniLM-L6-v2", "dimensions": 384}
WRITER_VERSIONS = {"lancedb": "0.37.1", "sentence-transformers": "5.7.0", "pyarrow": "25.0.1"}


def write_json(path, value):
    Path(path).write_text(json.dumps(value, sort_keys=True, indent=2), encoding="utf-8")


def digest(value):
    return hashlib.sha256(json.dumps(value, sort_keys=True).encode()).hexdigest()


def capture_corpus(pages, expected_urls, failed_urls=()):
    """Identify one completed crawl; a missing discovered page fails the build."""
    urls = [p["url"] for p in pages]
    if failed_urls or not urls or any(not u for u in urls) or len(urls) != len(set(urls)):
        raise ValueError("Incomplete crawl: failed, empty, or duplicate pages")
    if set(urls) != set(expected_urls):
        raise ValueError("Incomplete crawl: discovered URLs differ from captured pages")
    pages = sorted(pages, key=lambda p: p["url"])
    return {
        "format_version": FORMAT_VERSION,
        "source": "https://cua.ai/docs (links discovered from /docs)",
        "captured_at": datetime.now(timezone.utc).isoformat(),
        "corpus_id": digest(pages),
        "expected_urls": sorted(urls),
        "pages": pages,
    }


def load_corpus(path):
    corpus = json.loads(Path(path).read_text())
    checked = capture_corpus(corpus["pages"], corpus["expected_urls"])
    if (
        corpus.get("format_version") != FORMAT_VERSION
        or checked["corpus_id"] != corpus["corpus_id"]
    ):
        raise ValueError("Corpus identity mismatch")
    return corpus


def prepare_pages(corpus):
    from markdown_it import MarkdownIt

    parser = MarkdownIt()
    included, exclusions = [], []
    for page in corpus["pages"]:
        parts = []
        for token in parser.parse(page.get("markdown", "")):
            if token.type in ("fence", "code_block"):
                parts.append(token.content)
            elif token.type == "inline":
                parts.append(
                    " ".join(
                        c.content for c in token.children or [] if c.type in ("text", "code_inline")
                    )
                )
        text = "\n\n".join(parts).strip()
        if not text:
            exclusions.append({"url": page["url"], "reason": "no searchable text"})
            continue
        included.append({**page, "text": text})
    if not included:
        raise ValueError("Corpus has no searchable pages")
    return included, exclusions


def make_chunks(pages, build_id):
    """Keep short pages and short paragraphs; both indexes cover identical URLs."""
    return [
        {
            "text": page["text"][offset : offset + 1000],
            "url": page["url"],
            "title": page.get("title") or "Untitled",
            "category": page.get("path_info", {}).get("category") or "unknown",
            "chunk_index": index,
            "build_id": build_id,
        }
        for page in pages
        for index, offset in enumerate(range(0, len(page["text"]), 800))
    ]


def write_sqlite(path, pages, build_id, corpus):
    with sqlite3.connect(path) as conn:
        conn.executescript("""
            CREATE TABLE pages (id INTEGER PRIMARY KEY, url TEXT UNIQUE NOT NULL,
                title TEXT, category TEXT, content TEXT, build_id TEXT NOT NULL,
                description TEXT, subcategory TEXT, page_name TEXT, raw_markdown TEXT);
            CREATE VIRTUAL TABLE pages_fts USING fts5(content, url UNINDEXED,
                title UNINDEXED, category UNINDEXED, content='pages', content_rowid='id');
            CREATE TABLE index_metadata (build_id TEXT NOT NULL, corpus_id TEXT NOT NULL,
                captured_at TEXT NOT NULL, source TEXT NOT NULL);
        """)
        conn.execute(
            "INSERT INTO index_metadata VALUES (?,?,?,?)",
            (build_id, corpus["corpus_id"], corpus["captured_at"], corpus["source"]),
        )
        conn.executemany(
            "INSERT INTO pages (url,title,category,content,build_id,description,subcategory,page_name,raw_markdown) "
            "VALUES (?,?,?,?,?,?,?,?,?)",
            [
                (
                    p["url"],
                    p.get("title") or "Untitled",
                    p.get("path_info", {}).get("category") or "unknown",
                    p["text"],
                    build_id,
                    p.get("description", ""),
                    p.get("path_info", {}).get("subcategory"),
                    p.get("path_info", {}).get("page", ""),
                    p.get("markdown", ""),
                )
                for p in pages
            ],
        )
        conn.execute("INSERT INTO pages_fts(pages_fts) VALUES ('rebuild')")


def write_vectors(path, chunks):
    from importlib.metadata import version

    for package, expected in WRITER_VERSIONS.items():
        if version(package) != expected:
            raise RuntimeError(
                f"Use the docs-mcp-server locked environment: {package}=={expected} required"
            )
    import lancedb
    from lancedb.embeddings import get_registry
    from lancedb.pydantic import LanceModel, Vector

    model = get_registry().get("sentence-transformers").create(name=EMBEDDING["model"])

    class DocChunk(LanceModel):
        text: str = model.SourceField()
        vector: Vector(model.ndims()) = model.VectorField()
        url: str
        title: str
        category: str
        chunk_index: int
        build_id: str

    table = lancedb.connect(path).create_table("docs", schema=DocChunk)
    for offset in range(0, len(chunks), 100):
        table.add(chunks[offset : offset + 100])


def open_vectors(path):
    import lancedb

    return lancedb.connect(path).open_table("docs")


def validate_pair(path, manifest, table):
    conn = sqlite3.connect(
        f"{(Path(path) / 'docs.sqlite').as_uri()}?mode=ro", uri=True, check_same_thread=False
    )
    try:
        expected = set(manifest["included_urls"])
        if expected | {e["url"] for e in manifest["exclusions"]} != set(manifest["expected_urls"]):
            raise ValueError("Manifest corpus coverage mismatch")
        metadata = conn.execute(
            "SELECT build_id,corpus_id,captured_at,source FROM index_metadata"
        ).fetchall()
        if metadata != [
            (
                manifest["build_id"],
                manifest["corpus_id"],
                manifest["captured_at"],
                manifest["source"],
            )
        ]:
            raise ValueError("SQLite build identity mismatch")
        rows = conn.execute("SELECT url, build_id FROM pages").fetchall()
        vectors = (
            table.search().select(["url", "build_id"]).limit(manifest["chunk_count"] + 1).to_list()
        )
        if (
            {r[0] for r in rows} != expected
            or {r["url"] for r in vectors} != expected
            or len(rows) != len(expected)
            or len(vectors) != manifest["chunk_count"]
            or any(r[1] != manifest["build_id"] for r in rows)
            or any(r["build_id"] != manifest["build_id"] for r in vectors)
        ):
            raise ValueError("SQLite/vector corpus or build identity mismatch")
        conn.row_factory = sqlite3.Row
        return conn
    except Exception:
        conn.close()
        raise


def file_hash(path):
    with Path(path).open("rb") as stream:
        return hashlib.file_digest(stream, "sha256").hexdigest()


def build_generation(corpus, root, vector_writer=write_vectors, vector_opener=open_vectors):
    """Build without touching the active generation. Return only a verified pair."""
    checked = capture_corpus(corpus["pages"], corpus["expected_urls"])
    if checked["corpus_id"] != corpus["corpus_id"]:
        raise ValueError("Corpus identity mismatch")
    pages, exclusions = prepare_pages(corpus)
    build_id = uuid.uuid4().hex
    path = Path(root).resolve() / "generations" / build_id
    path.mkdir(parents=True)
    chunks = make_chunks(pages, build_id)
    write_sqlite(path / "docs.sqlite", pages, build_id, corpus)
    vector_writer(path, chunks)
    manifest = {
        "format_version": FORMAT_VERSION,
        "build_id": build_id,
        "corpus_id": corpus["corpus_id"],
        "source": corpus["source"],
        "captured_at": corpus["captured_at"],
        "embedding": EMBEDDING,
        "writer_versions": WRITER_VERSIONS,
        "expected_urls": corpus["expected_urls"],
        "included_urls": [p["url"] for p in pages],
        "exclusions": exclusions,
        "chunk_count": len(chunks),
    }
    validate_pair(path, manifest, vector_opener(path)).close()
    manifest["files"] = {
        p.relative_to(path).as_posix(): file_hash(p) for p in sorted(path.rglob("*")) if p.is_file()
    }
    write_json(path / "manifest.json", manifest)
    return path, manifest


def verify_files(path, manifest):
    if manifest.get("format_version") != FORMAT_VERSION or manifest.get("embedding") != EMBEDDING:
        raise ValueError("Unsupported docs generation")
    if not manifest.get("files") or "docs.sqlite" not in manifest["files"]:
        raise ValueError("Incomplete docs generation manifest")
    actual = {
        p.relative_to(path).as_posix()
        for p in Path(path).rglob("*")
        if p.is_file() and p != Path(path) / "manifest.json"
    }
    if actual != set(manifest["files"]):
        raise ValueError("Incomplete docs generation: file inventory mismatch")
    for name, sha in manifest["files"].items():
        file = Path(path) / name
        if (
            file.resolve().parent != Path(path).resolve()
            and Path(path).resolve() not in file.resolve().parents
        ):
            raise ValueError("Invalid generation file path")
        if not file.is_file() or file_hash(file) != sha:
            raise ValueError(f"Incomplete docs generation: {name}")


def pointer_for(manifest):
    return {"build_id": manifest["build_id"], "manifest_sha256": digest(manifest)}


def activate(root, manifest):
    """Local filesystems: replace the small pointer only after validation/copy."""
    root = Path(root)
    verify_files(root / "generations" / manifest["build_id"], manifest)
    staging = root / f".current-{uuid.uuid4().hex}.json"
    write_json(staging, pointer_for(manifest))
    staging.replace(root / "current.json")


def publish_generation(s3, bucket, path, manifest):
    """Immutable objects first, then one commit marker. Never delete old builds."""
    verify_files(path, manifest)
    if json.loads((Path(path) / "manifest.json").read_text()) != manifest:
        raise ValueError("Publication manifest mismatch")
    prefix = f"docs_db/generations/{manifest['build_id']}/"
    for name in sorted(manifest["files"]):
        s3.upload_file(str(Path(path) / name), bucket, prefix + name)
    s3.upload_file(str(Path(path) / "manifest.json"), bucket, prefix + "manifest.json")
    s3.put_object(
        Bucket=bucket,
        Key="docs_db/current.json",
        Body=json.dumps(pointer_for(manifest)).encode(),
        ContentType="application/json",
    )
    return len(manifest["files"]) + 2


def copy_generation(source, destination):
    """Copy a committed generation to local disk, then activate it atomically."""
    source, destination = Path(source), Path(destination)
    pointer = json.loads((source / "current.json").read_text())
    build_id = pointer["build_id"]
    if not re.fullmatch(r"[a-f0-9]{32}", build_id):
        raise ValueError("Invalid docs build id")
    if (destination / "current.json").exists():
        if json.loads((destination / "current.json").read_text()) == pointer:
            return
    origin = source / "generations" / build_id
    manifest = json.loads((origin / "manifest.json").read_text())
    if pointer != pointer_for(manifest):
        raise ValueError("Copy manifest identity mismatch")
    verify_files(origin, manifest)
    target = destination / "generations" / build_id
    shutil.copytree(origin, target, dirs_exist_ok=True)
    activate(destination, manifest)


class GenerationReader:
    """Refresh both handles together; reject bad candidates and keep last good."""

    def __init__(self, root, vector_opener=open_vectors, refresh=None):
        self.root = Path(root).resolve()
        self.vector_opener = vector_opener
        self.current = None
        self.error = None
        self.lock = threading.RLock()
        self.refresh = refresh

    def get(self):
        with self.lock:
            try:
                if self.refresh:
                    self.refresh()
                pointer = json.loads((self.root / "current.json").read_text())
                build_id = pointer["build_id"]
                if not re.fullmatch(r"[a-f0-9]{32}", build_id):
                    raise ValueError("Invalid docs build id")
                if self.current and pointer == pointer_for(self.current[2]):
                    self.error = None
                    return self.current
                path = self.root / "generations" / build_id
                manifest = json.loads((path / "manifest.json").read_text())
                if (
                    manifest["build_id"] != build_id
                    or digest(manifest) != pointer["manifest_sha256"]
                ):
                    raise ValueError("Manifest identity mismatch")
                verify_files(path, manifest)
                table = self.vector_opener(path)
                conn = validate_pair(path, manifest, table)
                # Requests retain their returned handle while a new generation opens.
                self.current = (conn, table, manifest)
                self.error = None
            except Exception as error:
                self.error = str(error)
                logging.warning("Docs generation refresh rejected: %s", error)
                if self.current is None:
                    raise RuntimeError("No verified docs generation available") from error
            return self.current

"""Bounded S3 consumer for the docs MCP paired-generation format.

Reads ``docs_db/current.json`` once, fetches exactly that generation's manifest
and allowlisted files into a staging directory on the destination filesystem,
verifies every hash, installs the immutable generation directory, and only then
replaces the local ``current.json`` atomically. Every failure leaves the last
good pointer, existing generations, flat legacy files, and code data untouched.
"""

import argparse
import fcntl
import json
import logging
import math
import os
import re
import shutil
import stat
import sys
import time
import uuid
from pathlib import Path, PurePosixPath

sys.path.insert(0, str(Path(__file__).resolve().parent))
import docs_index  # noqa: E402

log = logging.getLogger("sync_docs_index")

POINTER_KEY = "docs_db/current.json"
GENERATION_PREFIX = "docs_db/generations/"
BUILD_ID = re.compile(r"[a-f0-9]{32}")
SHA256 = re.compile(r"[a-f0-9]{64}")
MAX_POINTER_BYTES = 4 * 1024
MAX_MANIFEST_BYTES = 16 * 1024 * 1024
LOCK_NAME = ".sync-docs-index.lock"
STAGE_PREFIX = ".stage-"
MISSING_CODES = {"NoSuchKey", "404", "NotFound"}


class SyncError(RuntimeError):
    """Operational failure; last-good state is preserved."""


class MissingPointer(SyncError):
    """The remote ``docs_db/current.json`` object does not exist."""


class LockHeld(SyncError):
    """Another consumer holds the destination lock."""


def _is_missing(error):
    code = getattr(error, "response", None)
    if not isinstance(code, dict):
        return False
    return str(code.get("Error", {}).get("Code")) in MISSING_CODES


def read_json_object(s3, bucket, key, limit):
    """Fetch and parse one small JSON object, never reading more than ``limit`` bytes."""
    try:
        response = s3.get_object(Bucket=bucket, Key=key)
    except Exception as error:
        if _is_missing(error):
            raise MissingPointer(f"Missing object {key}") from error
        raise SyncError(f"Cannot read {key}: {type(error).__name__}") from error
    stream = response["Body"]
    try:
        length = response.get("ContentLength")
        if length is not None and int(length) > limit:
            raise ValueError(f"Object {key} exceeds {limit} bytes")
        body = stream.read(limit + 1)
    finally:
        stream.close()
    if len(body) > limit:
        raise ValueError(f"Object {key} exceeds {limit} bytes")
    try:
        value = json.loads(body.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as error:
        raise ValueError(f"Object {key} is not valid JSON") from error
    if not isinstance(value, dict):
        raise ValueError(f"Object {key} is not a JSON object")
    return value


def validate_pointer(pointer):
    if not isinstance(pointer, dict) or set(pointer) != {"build_id", "manifest_sha256"}:
        raise ValueError("Invalid docs pointer shape")
    if not isinstance(pointer["build_id"], str) or not BUILD_ID.fullmatch(pointer["build_id"]):
        raise ValueError("Invalid docs build id")
    if not isinstance(pointer["manifest_sha256"], str) or not SHA256.fullmatch(
        pointer["manifest_sha256"]
    ):
        raise ValueError("Invalid docs manifest hash")
    return pointer


def safe_relative_path(name):
    """Accept only ``docs.sqlite`` or plain relative paths beneath ``docs.lance/``."""
    if not isinstance(name, str) or not name or "\\" in name or "\0" in name:
        raise ValueError("Invalid generation file path")
    if name.startswith("/") or name.endswith("/") or "//" in name:
        raise ValueError("Invalid generation file path")
    parts = tuple(name.split("/"))
    if any(part in ("", ".", "..") for part in parts) or PurePosixPath(name).is_absolute():
        raise ValueError("Invalid generation file path")
    if name == "manifest.json" or parts[0] == "manifest.json":
        raise ValueError("Generation manifest collision")
    if name != "docs.sqlite" and not (parts[0] == "docs.lance" and len(parts) > 1):
        raise ValueError("Generation file outside docs.sqlite and docs.lance/")
    return parts


def validate_manifest(manifest, pointer):
    if not isinstance(manifest, dict):
        raise ValueError("Invalid docs manifest")
    if manifest.get("build_id") != pointer["build_id"]:
        raise ValueError("Manifest build id mismatch")
    if docs_index.digest(manifest) != pointer["manifest_sha256"]:
        raise ValueError("Manifest identity mismatch")
    if (
        manifest.get("format_version") != docs_index.FORMAT_VERSION
        or manifest.get("embedding") != docs_index.EMBEDDING
    ):
        raise ValueError("Unsupported docs generation")
    files = manifest.get("files")
    if not isinstance(files, dict) or "docs.sqlite" not in files:
        raise ValueError("Incomplete docs generation manifest")
    for name, sha in files.items():
        safe_relative_path(name)
        if not isinstance(sha, str) or not SHA256.fullmatch(sha):
            raise ValueError(f"Malformed digest for {name}")
    return manifest


def _reject_symlinks(path):
    for entry in [Path(path), *Path(path).rglob("*")]:
        if entry.is_symlink():
            raise ValueError("Symlink inside docs generation")


def verify_existing_generation(target, manifest):
    """An installed generation is immutable: it must already be this exact manifest."""
    if target.is_symlink() or not target.is_dir():
        raise ValueError("Existing generation path is not a directory")
    _reject_symlinks(target)
    manifest_file = target / "manifest.json"
    if not manifest_file.is_file() or manifest_file.stat().st_size > MAX_MANIFEST_BYTES:
        raise ValueError("Existing generation manifest unreadable")
    try:
        installed = json.loads(manifest_file.read_text(encoding="utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as error:
        raise ValueError("Existing generation manifest corrupt") from error
    if installed != manifest:
        raise ValueError("Existing generation conflicts with remote manifest")
    docs_index.verify_files(target, manifest)


def _read_local_pointer(destination):
    pointer_file = destination / "current.json"
    try:
        if not pointer_file.is_file() or pointer_file.stat().st_size > MAX_POINTER_BYTES:
            return None
        return json.loads(pointer_file.read_text(encoding="utf-8"))
    except (OSError, UnicodeDecodeError, json.JSONDecodeError):
        return None


def _stage_generation(s3, bucket, manifest, destination):
    build_id = manifest["build_id"]
    generations = destination / "generations"
    stage = generations / f"{STAGE_PREFIX}{build_id}-{uuid.uuid4().hex}"
    stage.mkdir()
    try:
        for name in sorted(manifest["files"]):
            parts = safe_relative_path(name)
            file = stage.joinpath(*parts)
            file.parent.mkdir(parents=True, exist_ok=True)
            try:
                s3.download_file(bucket, f"{GENERATION_PREFIX}{build_id}/{name}", str(file))
            except Exception as error:
                raise SyncError(f"Download failed: {type(error).__name__}") from error
        docs_index.write_json(stage / "manifest.json", manifest)
        _reject_symlinks(stage)
        docs_index.verify_files(stage, manifest)
        return stage
    except BaseException:
        # Only this process's own incomplete staging directory is discarded.
        if stage.parent == generations and stage.name.startswith(STAGE_PREFIX):
            shutil.rmtree(stage, ignore_errors=True)
        raise


def _install(stage, target, manifest):
    try:
        stage.rename(target)
    except OSError:
        shutil.rmtree(stage, ignore_errors=True)
        if not target.exists():
            raise
        # A concurrent installer won; accept only an identical generation.
        verify_existing_generation(target, manifest)
        return False
    return True


class destination_lock:
    """Advisory flock on the destination so overlapping consumers serialize."""

    def __init__(self, destination, timeout):
        self.path = Path(destination) / LOCK_NAME
        self.timeout = timeout
        self.fd = None

    def __enter__(self):
        self.fd = os.open(self.path, os.O_RDWR | os.O_CREAT | os.O_NOFOLLOW, 0o644)
        if not stat.S_ISREG(os.fstat(self.fd).st_mode):
            os.close(self.fd)
            self.fd = None
            raise ValueError("Docs sync lock is not a regular file")
        deadline = time.monotonic() + self.timeout
        while True:
            try:
                fcntl.flock(self.fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
                return self
            except BlockingIOError:
                if time.monotonic() >= deadline:
                    os.close(self.fd)
                    self.fd = None
                    raise LockHeld("Another docs sync holds the destination lock") from None
                time.sleep(0.05)

    def __exit__(self, *exc):
        fcntl.flock(self.fd, fcntl.LOCK_UN)
        os.close(self.fd)
        self.fd = None
        return False


def sync(s3, bucket, destination, *, allow_missing_pointer=False, lock_timeout=300.0):
    """Install and activate the generation named by the remote pointer, read once."""
    if not math.isfinite(lock_timeout) or lock_timeout < 0:
        raise ValueError("Lock timeout must be finite and nonnegative")
    if Path(destination).is_symlink():
        raise ValueError("Docs destination is a symlink")
    destination = Path(destination).resolve()
    destination.mkdir(parents=True, exist_ok=True)
    generations = destination / "generations"
    if generations.is_symlink():
        raise ValueError("Docs generations directory is a symlink")
    generations.mkdir(exist_ok=True)
    with destination_lock(destination, lock_timeout):
        local_pointer = destination / "current.json"
        if local_pointer.is_symlink():
            raise ValueError("Docs current pointer is a symlink")
        try:
            pointer = read_json_object(s3, bucket, POINTER_KEY, MAX_POINTER_BYTES)
        except MissingPointer:
            if allow_missing_pointer and not local_pointer.exists():
                log.info("No remote docs pointer; initial migration leaves no local pointer")
                return {"status": "no-remote-pointer", "build_id": None, "files": 0}
            raise
        validate_pointer(pointer)
        build_id = pointer["build_id"]
        manifest = validate_manifest(
            read_json_object(
                s3, bucket, f"{GENERATION_PREFIX}{build_id}/manifest.json", MAX_MANIFEST_BYTES
            ),
            pointer,
        )
        target = generations / build_id
        if target.exists() or target.is_symlink():
            verify_existing_generation(target, manifest)
            installed = False
        else:
            stage = _stage_generation(s3, bucket, manifest, destination)
            installed = _install(stage, target, manifest)
        activated = _read_local_pointer(destination) != docs_index.pointer_for(manifest)
        if activated:
            docs_index.activate(destination, manifest)
        status = "installed" if installed else ("activated" if activated else "current")
        log.info("Docs generation %s: %s (%d files)", build_id, status, len(manifest["files"]))
        return {"status": status, "build_id": build_id, "files": len(manifest["files"])}


def main(argv=None):
    parser = argparse.ArgumentParser(description="Sync the docs MCP generation from S3.")
    parser.add_argument("--bucket", default=os.environ.get("DOCS_BUCKET"), help="S3 bucket name")
    parser.add_argument(
        "--root", default=os.environ.get("DOCS_DB_PATH"), help="Local docs_db destination"
    )
    parser.add_argument(
        "--allow-missing-pointer",
        action="store_true",
        help="Succeed without a remote pointer only when no local current.json exists yet",
    )
    parser.add_argument("--lock-timeout", type=float, default=300.0)
    args = parser.parse_args(argv)
    if not args.bucket or not args.root:
        parser.error("--bucket and --root (or DOCS_BUCKET / DOCS_DB_PATH) are required")
    logging.basicConfig(level=logging.INFO, format="%(levelname)s %(message)s")
    import boto3

    try:
        result = sync(
            boto3.client("s3"),
            args.bucket,
            args.root,
            allow_missing_pointer=args.allow_missing_pointer,
            lock_timeout=args.lock_timeout,
        )
    except Exception as error:
        # SDK and filesystem exceptions can carry endpoint, credential, or path details.
        log.error("Docs sync failed: %s", type(error).__name__)
        return 1
    print(json.dumps(result, sort_keys=True))
    return 0


if __name__ == "__main__":
    sys.exit(main())

