test('recorded live choices replay through the new state', async () => {
  for (const [name, run] of Object.entries<any>(FIXTURE.recorded_live_runs)) {
    const client = replayClient(run.steps);
    const history: HistoryEntry[] = [];
    let outcome = 'budget_exhausted';
    for (let step = 1; step <= 4; step += 1) {
      const snapshot = step === 1 ? BEFORE : AFTER;
      const candidates = buildCandidates(snapshot, TOKEN);
      const recorded: RecordedStep = run.steps[step - 1];
      assert.deepEqual(
        new Set(Object.keys(recorded.probabilities)),
        new Set(candidates.map((candidate) => candidate.id)),
        name
      );
      const answer = await chooseWithTypeSafe(
        client as never,
        candidates,
        snapshot,
        undefined,
        history,
        TOKEN
      );
      const candidate = validateChoice(answer.choice, candidates);
      const request = client.requests.at(-1);
      assert.equal(JSON.stringify(request.state).includes(TOKEN), false, name);
      assert.equal(
        JSON.parse(request.state.observation.form).verification_field,
        step === 1 ? 'empty' : 'contains_required_token',
        name
      );
      for (const item of JSON.parse(request.state.history)) {
        assert.deepEqual(Object.keys(item).sort(), ['outcome', 'selected_id', 'step'], name);
      }
      const criteria = request.questions.driver_action.criteria;
      assert.ok('reobserve' in criteria && 'abstain' in criteria, name);
      history.push(historyEntry(step, candidate.id));
      if (candidate.id === 'submit-form') {
        outcome = 'verified';
        break;
      }
    }
    assert.equal(outcome, run.outcome, name);
  }
});

import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import test from 'node:test';

import {
  SUBMIT_IDS,
  buildCandidates,
  chooseMock,
  formState,
  hasExecutableCandidate,
  historyEntry,
  parseVisualRegions,
  validateChoice,
  visualSubmitRegion,
  type BrowserSnapshot,
  type HistoryEntry,
  type VisualDelivery,
  type VisualObservation,
} from './core.js';
import { chooseWithTypeSafe, decisionState } from './jev_adapter.js';

const load = (name: string) =>
  JSON.parse(readFileSync(new URL(`../fixtures/${name}`, import.meta.url), 'utf8'));
const VISUAL = load('jev-visual-replay-v1.json');
const PAGE = load('jev-page-structure-replay-v1.json');
const TOKEN: <REDACTED> = VISUAL.token;
const BEFORE: BrowserSnapshot = VISUAL.snapshots.before_typing;
const AFTER: BrowserSnapshot = VISUAL.snapshots.after_typing;
const PAYLOAD = VISUAL.visual_regions;

type RecordedStep = {
  step: number;
  selected_id: string;
  probabilities: Record<string, number>;
  action_error?: string;
};

function observation(): VisualObservation {
  const source = PAYLOAD.capture.source;
  return parseVisualRegions(PAYLOAD, PAYLOAD.capture.capture_id, source.pid, source.window_id);
}

function replayClient(recorded: RecordedStep[]) {
  const queue = [...recorded];
  const requests: any[] = [];
  return {
    requests,
    systemOne: async (request: any) => {
      requests.push(request);
      const step = queue.shift()!;
      return {
        answers: {
          driver_action: {
            type: 'choice' as const,
            choice: step.selected_id,
            confidence: Math.max(...Object.values(step.probabilities)),
            probabilities: step.probabilities,
          },
        },
      };
    },
  };
}

test('visual fixture exposes Submit only as text and as one visual region', () => {
  for (const snapshot of [BEFORE, AFTER]) {
    assert.equal(
      (snapshot.refs ?? []).some((ref) => ref.role === 'button'),
      false
    );
    assert.ok((snapshot.outline ?? '').includes('statictext "Submit"'));
  }
  assert.equal(visualSubmitRegion(observation())?.text, 'Submit');
});

test('submit state names the visual path instead of a missing button', () => {
  const visual = observation();
  assert.equal(formState(BEFORE, TOKEN).submit_button, 'not_in_page_structure');
  assert.deepEqual(formState(BEFORE, TOKEN, undefined, true), {
    verification_field: 'empty',
    submit_button: 'visual_check_pending',
  });
  assert.deepEqual(formState(AFTER, TOKEN, visual, true), {
    verification_field: 'contains_required_token',
    submit_button: 'visual_only',
  });
  const withoutSubmit = { ...visual, regions: visual.regions.filter((r) => r.text !== 'Submit') };
  assert.equal(formState(AFTER, TOKEN, withoutSubmit, true).submit_button, 'not_found_visually');
  const submit = visualSubmitRegion(visual)!;
  const duplicated = { ...visual, regions: [...visual.regions, { ...submit, id: 'dup' }] };
  assert.equal(formState(AFTER, TOKEN, duplicated, true).submit_button, 'not_found_visually');
  // A page-structure Submit ref always wins, with or without a visual path.
  assert.equal(
    formState(PAGE.snapshots.after_typing, PAGE.token, visual, true).submit_button,
    'available'
  );
});

test('pre-fix step-one state contradicted the outline', () => {
  const old = VISUAL.pre_fix_step1;
  assert.equal(old.state.observation.form.submit_button, 'not_in_page_structure');
  assert.ok(old.state.observation.outline.includes('statictext "Submit"'));
  assert.ok(old.criteria.reobserve.includes('incomplete'));

  const state = decisionState(BEFORE, undefined, [], TOKEN, true);
  assert.deepEqual(JSON.parse(state.observation.form), {
    verification_field: 'empty',
    submit_button: 'visual_check_pending',
  });
  assert.equal(state.observation.outline, old.state.observation.outline);

  const criteria = Object.fromEntries(
    buildCandidates(BEFORE, TOKEN).map((candidate) => [candidate.id, candidate.description])
  );
  assert.deepEqual(Object.keys(criteria), Object.keys(old.criteria));
  assert.equal(criteria.reobserve.includes('incomplete'), false);
  assert.ok(criteria.reobserve.includes('visual-only'));
  assert.ok(criteria.reobserve.includes('still pending'));
});

test('page-structure fixture types then submits with browser_click', () => {
  const first = buildCandidates(PAGE.snapshots.before_typing, PAGE.token);
  assert.equal(chooseMock(first).choice, 'type-verification-value');
  const second = buildCandidates(PAGE.snapshots.after_typing, PAGE.token);
  const choice = validateChoice(chooseMock(second).choice!, second);
  assert.deepEqual([choice.id, choice.tool], ['submit-form', 'browser_click']);
});

test('visual fixture types then submits with a capture-bound click', () => {
  const first = buildCandidates(BEFORE, TOKEN, undefined, true);
  const typed = validateChoice(chooseMock(first).choice!, first);
  assert.deepEqual([typed.id, typed.tool], ['type-verification-value', 'browser_type']);

  // After typing the page structure offers no action, so the runner parses.
  assert.equal(hasExecutableCandidate(buildCandidates(AFTER, TOKEN, undefined, true)), false);
  const visual = observation();
  const second = buildCandidates(AFTER, TOKEN, visual, true);
  const submit = validateChoice(chooseMock(second).choice!, second, visual.captureId);
  const region = visualSubmitRegion(visual)!;
  assert.deepEqual([submit.id, submit.tool], ['submit-form', 'click']);
  assert.equal(submit.arguments.capture_id, visual.captureId);
  assert.equal(submit.arguments.delivery_mode, 'background');
  assert.deepEqual(
    [submit.arguments.x, submit.arguments.y],
    [region.x + region.width / 2, region.y + region.height / 2]
  );

  const third = buildCandidates(AFTER, TOKEN, visual, true, 'foreground');
  const foreground = validateChoice(chooseMock(third).choice!, third, visual.captureId);
  assert.deepEqual(
    [foreground.id, foreground.arguments.delivery_mode],
    ['submit-form-foreground', 'foreground']
  );
});

test('recorded visual-run choices replay through the new state', async () => {
  const visual = observation();
  for (const [name, run] of Object.entries<any>(VISUAL.recorded_live_runs)) {
    const client = replayClient(run.steps);
    const history: HistoryEntry[] = [];
    let typed = false;
    let delivery: VisualDelivery = 'background';
    let outcome = 'budget_exhausted';
    for (const recorded of run.steps as RecordedStep[]) {
      const snapshot = typed ? AFTER : BEFORE;
      const current = typed ? visual : undefined;
      const candidates = buildCandidates(snapshot, TOKEN, current, true, delivery);
      assert.deepEqual(
        new Set(Object.keys(recorded.probabilities)),
        new Set(candidates.map((candidate) => candidate.id)),
        name
      );
      const answer = await chooseWithTypeSafe(
        client as never,
        candidates,
        snapshot,
        current,
        history,
        TOKEN,
        true
      );
      const candidate = validateChoice(answer.choice, candidates, current?.captureId);
      const request = client.requests.at(-1);
      assert.equal(JSON.stringify(request.state).includes(TOKEN), false, name);
      assert.deepEqual(
        JSON.parse(request.state.observation.form),
        {
          verification_field: typed ? 'contains_required_token' : 'empty',
          submit_button: typed ? 'visual_only' : 'visual_check_pending',
        },
        name
      );
      assert.equal(
        request.questions.driver_action.criteria.reobserve.includes('incomplete'),
        false
      );
      for (const item of JSON.parse(request.state.history)) {
        assert.deepEqual(Object.keys(item).sort(), ['outcome', 'selected_id', 'step'], name);
      }
      history.push(historyEntry(recorded.step, candidate.id, recorded.action_error));
      if (candidate.id === 'type-verification-value') {
        typed = true;
      } else if (SUBMIT_IDS.has(candidate.id)) {
        assert.equal(candidate.tool, 'click', name);
        if (recorded.action_error) {
          delivery = 'foreground';
        } else {
          outcome = 'verified';
          break;
        }
      }
    }
    assert.equal(outcome, run.outcome, name);
  }
});

//! A pull never runs the user's docker credential helper unless the registry
//! refuses anonymous access. Docker Desktop's helper makes macOS ask "Cua
//! Spaces would like to access data from other apps", so a Space created
//! from a public image (`ghcr.io/trycua/linux:24.04`) must not start it.
//!
//! Hermetic: a loopback registry (one public repository, one that wants
//! Basic auth), a throwaway docker config with `"credsStore": "r7fake"` and a
//! fake `docker-credential-r7fake` first on `PATH` that logs each call. Its
//! own test binary, since it sets env vars.

use std::path::PathBuf;
use std::sync::{Arc, Mutex};

use base64::Engine;
use cua_image::digest::sha256_bytes;
use cua_image::{ImageError, RegistryClient, auth};
use serde_json::json;
use tokio::io::{AsyncReadExt, AsyncWriteExt};
use tokio::net::TcpListener;

/// The env vars below are process-wide: one test at a time.
static ENV: tokio::sync::Mutex<()> = tokio::sync::Mutex::const_new(());

const PUBLIC: &str = "pub/app";
const PRIVATE: &str = "team/app";
const BASIC: &str = "bot:s3cret";

struct Registry {
    host: String,
    /// `(path, sent credentials)` for every request, in order.
    requests: Arc<Mutex<Vec<(String, bool)>>>,
    server: tokio::task::JoinHandle<()>,
}

impl Registry {
    async fn start() -> Self {
        let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let host = format!("127.0.0.1:{}", listener.local_addr().unwrap().port());
        let manifest = serde_json::to_vec(&json!({
            "schemaVersion": 2,
            "mediaType": "application/vnd.oci.image.manifest.v1+json",
            "config": {"mediaType": "application/vnd.oci.image.config.v1+json",
                "digest": sha256_bytes(b"{}"), "size": 2},
            "layers": []
        }))
        .unwrap();
        let requests = Arc::new(Mutex::new(Vec::new()));
        let seen = requests.clone();
        let want = base64::engine::general_purpose::STANDARD.encode(BASIC);
        let server = tokio::spawn(async move {
            // Bounded: the test aborts this task; one request per connection.
            for _ in 0..200 {
                let Ok((mut s, _)) = listener.accept().await else {
                    return;
                };
                let (manifest, seen, want) = (manifest.clone(), seen.clone(), want.clone());
                tokio::spawn(async move {
                    let mut buf = vec![0u8; 16 << 10];
                    let mut n = 0;
                    while n < buf.len() {
                        let Ok(k) = s.read(&mut buf[n..]).await else {
                            return;
                        };
                        if k == 0 {
                            return;
                        }
                        n += k;
                        if buf[..n].windows(4).any(|w| w == b"\r\n\r\n") {
                            break;
                        }
                    }
                    let req = String::from_utf8_lossy(&buf[..n]).to_string();
                    let path = req.split_whitespace().nth(1).unwrap_or("").to_string();
                    let authed = req.lines().any(|l| {
                        l.to_ascii_lowercase().starts_with("authorization:") && l.contains(&want)
                    });
                    seen.lock().unwrap().push((path.clone(), authed));
                    let public = path.contains(&format!("/v2/{PUBLIC}/"));
                    let (status, headers, body): (&str, String, Vec<u8>) = if !authed && !public {
                        (
                            "401 Unauthorized",
                            "WWW-Authenticate: Basic realm=\"fake\"\r\n".into(),
                            br#"{"errors":[{"code":"UNAUTHORIZED","message":"auth required"}]}"#
                                .to_vec(),
                        )
                    } else if path == "/v2/" {
                        ("200 OK", String::new(), b"{}".to_vec())
                    } else if path.contains("/manifests/") {
                        (
                            "200 OK",
                            format!(
                                "Content-Type: application/vnd.oci.image.manifest.v1+json\r\n\
                                     Docker-Content-Digest: {}\r\n",
                                sha256_bytes(&manifest)
                            ),
                            manifest.clone(),
                        )
                    } else {
                        ("404 Not Found", String::new(), b"{}".to_vec())
                    };
                    let head = format!(
                        "HTTP/1.1 {status}\r\n{headers}Content-Length: {}\r\nConnection: close\r\n\r\n",
                        body.len()
                    );
                    let _ = s.write_all(head.as_bytes()).await;
                    let _ = s.write_all(&body).await;
                });
            }
        });
        Self {
            host,
            requests,
            server,
        }
    }

    fn reference(&self, repo: &str) -> String {
        format!("{}/{repo}:1", self.host)
    }

    fn client(&self) -> RegistryClient {
        RegistryClient::new(vec![self.host.clone()])
    }

    /// Manifest requests that carried credentials / that did not.
    fn manifest_requests(&self) -> (usize, usize) {
        let all = self.requests.lock().unwrap();
        let manifests = all.iter().filter(|(p, _)| p.contains("/manifests/"));
        (
            manifests.clone().filter(|(_, a)| *a).count(),
            manifests.filter(|(_, a)| !*a).count(),
        )
    }
}

impl Drop for Registry {
    fn drop(&mut self) {
        self.server.abort();
    }
}

/// A docker config with `credsStore: r7fake` (or `inline` credentials for
/// the registry) and a fake `docker-credential-r7fake` first on `PATH`.
struct Env {
    _dir: tempfile::TempDir,
    log: PathBuf,
}

impl Env {
    fn new(inline_for: Option<&str>) -> Self {
        let dir = tempfile::tempdir().unwrap();
        let bin = dir.path().join("bin");
        std::fs::create_dir(&bin).unwrap();
        let helper = bin.join("docker-credential-r7fake");
        // The docker credential helper protocol: `get`, the registry on
        // stdin, `{"Username", "Secret"}` on stdout.
        std::fs::write(
            &helper,
            "#!/bin/sh\necho \"$1 $(cat)\" >> \"$R7_HELPER_LOG\"\n\
             printf '{\"ServerURL\":\"x\",\"Username\":\"bot\",\"Secret\":\"s3cret\"}'\n",
        )
        .unwrap();
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            std::fs::set_permissions(&helper, std::fs::Permissions::from_mode(0o755)).unwrap();
        }
        let mut cfg = json!({"credsStore": "r7fake"});
        if let Some(host) = inline_for {
            cfg["auths"] =
                json!({host: {"auth": base64::engine::general_purpose::STANDARD.encode(BASIC)}});
        }
        std::fs::write(dir.path().join("config.json"), cfg.to_string()).unwrap();
        let log = dir.path().join("helper.log");
        let path = std::env::var_os("PATH").unwrap_or_default();
        let mut paths = vec![bin];
        paths.extend(std::env::split_paths(&path));
        unsafe {
            std::env::set_var("PATH", std::env::join_paths(paths).unwrap());
            std::env::set_var("DOCKER_CONFIG", dir.path());
            std::env::set_var("R7_HELPER_LOG", &log);
            std::env::remove_var("CUA_REGISTRY_CRED_HELPERS");
            for k in [
                "CUA_REGISTRY_USERNAME",
                "CUA_REGISTRY_PASSWORD",
                "CUA_REGISTRY_HOST",
                "GITHUB_TOKEN",
            ] {
                std::env::remove_var(k);
            }
        }
        Self { _dir: dir, log }
    }

    /// The registries the helper was asked for, one per call.
    fn helper_calls(&self) -> Vec<String> {
        std::fs::read_to_string(&self.log)
            .unwrap_or_default()
            .lines()
            .map(str::to_string)
            .collect()
    }
}

fn is_manifest(m: &cua_image::manifest::Manifest) -> bool {
    matches!(m, cua_image::manifest::Manifest::Image(_))
}

#[tokio::test]
async fn a_public_image_never_runs_the_credential_helper() {
    let _guard = ENV.lock().await;
    let reg = Registry::start().await;
    let env = Env::new(None);
    let client = reg.client();

    let (m, digest) = client.manifest(&reg.reference(PUBLIC)).await.unwrap();
    assert!(is_manifest(&m));
    assert!(digest.starts_with("sha256:"));
    client.manifest_bytes(&reg.reference(PUBLIC)).await.unwrap();
    let (pinned, _, _) = client
        .resolve_platform(&reg.reference(PUBLIC), "arm64")
        .await
        .unwrap();
    assert!(pinned.starts_with(&format!("{}/{PUBLIC}@sha256:", reg.host)));

    assert_eq!(env.helper_calls(), Vec::<String>::new());
    let (with_creds, anonymous) = reg.manifest_requests();
    assert_eq!((with_creds, anonymous), (0, 3), "all anonymous");
}

#[tokio::test]
async fn the_old_pull_chain_ran_the_helper_for_the_same_public_image() {
    // What every pull did before: the whole chain, helper first. It is still
    // the chain pushes use, and what `resolve_quiet` leaves out.
    let _guard = ENV.lock().await;
    let reg = Registry::start().await;
    let env = Env::new(None);

    let (_, source) = auth::resolve_quiet(&reg.host).await;
    assert_eq!(source, auth::AuthSource::Anonymous);
    assert_eq!(env.helper_calls(), Vec::<String>::new());

    let (_, source) = auth::resolve(&reg.host).await;
    assert_eq!(source, auth::AuthSource::CredentialHelper("r7fake".into()));
    assert_eq!(env.helper_calls(), vec![format!("get {}", reg.host)]);
}

#[tokio::test]
async fn a_private_image_asks_the_helper_once_after_anonymous_access_is_refused() {
    let _guard = ENV.lock().await;
    let reg = Registry::start().await;
    let env = Env::new(None);
    let client = reg.client();
    let r = reg.reference(PRIVATE);

    // The refused anonymous try, then the helper's credentials.
    let (m, _) = client.manifest(&r).await.unwrap();
    assert!(is_manifest(&m));
    assert_eq!(env.helper_calls(), vec![format!("get {}", reg.host)]);
    assert_eq!(reg.manifest_requests(), (1, 1));

    // Remembered: no second refusal, no second helper call.
    client.manifest(&r).await.unwrap();
    client.manifest_bytes(&r).await.unwrap();
    assert_eq!(env.helper_calls().len(), 1);
    assert_eq!(reg.manifest_requests(), (3, 1));

    // A new client tries anonymously itself, but reuses the helper's answer.
    reg.client().manifest(&r).await.unwrap();
    assert_eq!(env.helper_calls().len(), 1);
    assert_eq!(reg.manifest_requests(), (4, 2));

    // The public repository on the same registry still goes out anonymously.
    client.manifest(&reg.reference(PUBLIC)).await.unwrap();
    assert_eq!(env.helper_calls().len(), 1);
    assert_eq!(reg.manifest_requests(), (4, 3));
}

#[tokio::test]
async fn a_private_image_without_helper_credentials_stays_unauthorized() {
    let _guard = ENV.lock().await;
    let reg = Registry::start().await;
    let env = Env::new(None);
    unsafe { std::env::set_var("CUA_REGISTRY_CRED_HELPERS", "0") };

    let e = reg
        .client()
        .manifest(&reg.reference(PRIVATE))
        .await
        .unwrap_err();
    assert!(matches!(e, ImageError::Unauthorized(_)), "{e:?}");
    assert_eq!(env.helper_calls(), Vec::<String>::new());
    unsafe { std::env::remove_var("CUA_REGISTRY_CRED_HELPERS") };
}

#[tokio::test]
async fn inline_credentials_are_used_at_once_without_the_helper() {
    let _guard = ENV.lock().await;
    let reg = Registry::start().await;
    let env = Env::new(Some(&reg.host));

    reg.client()
        .manifest(&reg.reference(PRIVATE))
        .await
        .unwrap();
    assert_eq!(env.helper_calls(), Vec::<String>::new());
    assert_eq!(reg.manifest_requests(), (1, 0));
}

